import React, { useEffect, useRef, useState } from 'react';
import ReactDOM from 'react-dom';
import FeatherIcon from 'feather-icons-react';
import './RecruitmentPopup.css';

const DISMISS_KEY = 'imx-recruitment-popup-dismissed-date-v2';

function getTodayKey() {
    const now = new Date();
    const offset = now.getTimezoneOffset() * 60 * 1000;
    return new Date(now.getTime() - offset).toISOString().slice(0, 10);
}

function RecruitmentPopup() {
    const [isOpen, setIsOpen] = useState(false);
    const [position, setPosition] = useState(null);
    const popupRef = useRef(null);
    const dragRef = useRef(null);

    useEffect(() => {
        let dismissedToday = false;

        try {
            dismissedToday = localStorage.getItem(DISMISS_KEY) === getTodayKey();
        } catch (error) {
            // The notice should still work when browser storage is unavailable.
        }

        if (!dismissedToday) {
            const openTimer = window.setTimeout(() => setIsOpen(true), 350);
            return () => window.clearTimeout(openTimer);
        }
    }, []);

    useEffect(() => {
        if (!isOpen) return undefined;

        const handleKeyDown = (event) => {
            if (event.key === 'Escape') setIsOpen(false);
        };

        window.addEventListener('keydown', handleKeyDown);
        return () => {
            window.removeEventListener('keydown', handleKeyDown);
        };
    }, [isOpen]);

    const startDragging = (event) => {
        if (event.button !== 0 || window.innerWidth <= 575 || event.target.closest('button')) return;

        const popupBounds = popupRef.current.getBoundingClientRect();
        dragRef.current = {
            offsetX: event.clientX - popupBounds.left,
            offsetY: event.clientY - popupBounds.top
        };
        event.currentTarget.setPointerCapture(event.pointerId);
    };

    const dragPopup = (event) => {
        if (!dragRef.current || !popupRef.current) return;

        const popupBounds = popupRef.current.getBoundingClientRect();
        const left = Math.min(
            Math.max(8, event.clientX - dragRef.current.offsetX),
            window.innerWidth - popupBounds.width - 8
        );
        const top = Math.min(
            Math.max(8, event.clientY - dragRef.current.offsetY),
            window.innerHeight - Math.min(popupBounds.height, window.innerHeight - 16) - 8
        );

        setPosition({ left, top });
    };

    const stopDragging = (event) => {
        dragRef.current = null;
        if (event.currentTarget.hasPointerCapture(event.pointerId)) {
            event.currentTarget.releasePointerCapture(event.pointerId);
        }
    };

    const dismissForToday = () => {
        try {
            localStorage.setItem(DISMISS_KEY, getTodayKey());
        } catch (error) {
            // Closing is still allowed when browser storage is unavailable.
        }
        setIsOpen(false);
    };

    if (!isOpen) return null;

    return ReactDOM.createPortal(
        <div
            className="recruitment-popup-backdrop"
            role="presentation"
        >
            <section
                ref={popupRef}
                className="recruitment-popup"
                role="dialog"
                aria-modal="false"
                aria-labelledby="recruitment-popup-title"
                aria-describedby="recruitment-popup-description"
                style={position ? { left: `${position.left}px`, top: `${position.top}px`, right: 'auto' } : undefined}
            >
                <div
                    className="recruitment-popup-windowbar"
                    onPointerDown={startDragging}
                    onPointerMove={dragPopup}
                    onPointerUp={stopDragging}
                    onPointerCancel={stopDragging}
                >
                    <div className="recruitment-popup-windowdots" aria-hidden="true">
                        <span /><span /><span />
                    </div>
                    <span className="recruitment-popup-windowtitle">IMX LAB NOTICE</span>
                    <button
                        type="button"
                        className="recruitment-popup-close"
                        aria-label="모집 공고 팝업 닫기"
                        onClick={() => setIsOpen(false)}
                    >
                        <FeatherIcon icon="x" size="18" />
                    </button>
                </div>
                <div className="recruitment-popup-accent" aria-hidden="true" />

                <div className="recruitment-popup-header">
                    <div className="recruitment-popup-eyebrow">
                        <span className="recruitment-popup-dot" aria-hidden="true" />
                        IMX LAB · RECRUITING
                    </div>
                    <h2 id="recruitment-popup-title">학부생 인턴 및<br className="d-sm-none" /> 대학원생 모집</h2>
                    <p id="recruitment-popup-description">
                        VR/AR 분야에 관심이 있고,<br />
                        창의적인 아이디어를 직접 구현하고 싶은 학생을 모집합니다.
                    </p>
                </div>

                <div className="recruitment-popup-body">
                    <div className="recruitment-popup-section">
                        <div className="recruitment-popup-section-title">
                            <FeatherIcon icon="gift" size="17" />
                            <span>지원 사항</span>
                        </div>
                        <div className="recruitment-popup-benefits">
                            <span>
                                <FeatherIcon icon="check" size="14" />
                                <span>인건비 지원<small>참여 과제 대비</small></span>
                            </span>
                            <span>
                                <FeatherIcon icon="check" size="14" />
                                <span>연구 활동 지원<small>PC, AI 구독, 학회 출장 등</small></span>
                            </span>
                            <span>
                                <FeatherIcon icon="check" size="14" />
                                <span>연구 공간 지원<small>2027-1학기부터</small></span>
                            </span>
                        </div>
                    </div>

                    <div className="recruitment-popup-project">
                        <div className="recruitment-popup-project-label">참여 예정 연구 과제</div>
                        <p>
                            메타버스 환경 내 휴먼 인증 강화를 위한 몰입형 CAPTCHA 개발 및
                            AI 모방 불가 인간 행동 데이터셋 구축
                        </p>
                        <small className="recruitment-popup-project-meta">
                            한국연구재단 우수신진연구과제 · 2029년 2월까지
                        </small>
                    </div>

                    <div className="recruitment-popup-contact">
                        <a href="mailto:khseob0715@korea.ac.kr">
                            <span className="recruitment-popup-contact-icon"><FeatherIcon icon="mail" size="18" /></span>
                            <span><small>이메일 문의</small>khseob0715@korea.ac.kr</span>
                        </a>
                        <div>
                            <span className="recruitment-popup-contact-icon"><FeatherIcon icon="map-pin" size="18" /></span>
                            <span><small>방문 면담</small>가속기 ICT융합관 402호</span>
                        </div>
                    </div>
                </div>

                <div className="recruitment-popup-footer">
                    <button type="button" className="recruitment-popup-today" onClick={dismissForToday}>
                        오늘 하루 보지 않기
                    </button>
                </div>
            </section>
        </div>,
        document.body
    );
}

export default RecruitmentPopup;
