import React from 'react';
import { useParams, Link } from 'react-router-dom';
import { postData } from './PostData';
import NotFound from './NotFound';
import FeatherIcon from 'feather-icons-react';

const Bar = ({ label, value }) => (
    <div className="va-bar-row">
        <div className="va-bar-label">{label}</div>
        <div className="va-bar-track">
            <div className="va-bar-fill" style={{ width: `${value}%` }} />
        </div>
        <div className="va-bar-value">{value}</div>
    </div>
);

const ConditionCard = ({ item, barLabels }) => (
    <div className={`va-condition-card ${item.badge ? 'is-best' : ''}`}>
        <div className="d-flex justify-content-between align-items-start mb-2">
            <div>
                <div className="va-code">{item.code}</div>
                <h4>{item.title}</h4>
            </div>
            {item.badge && <span className="va-best-badge">{item.badge}</span>}
        </div>
        <p className="va-condition-label" style={{ minHeight: item.subtitle ? '2.5em' : 'auto' }}>{item.label || item.subtitle}</p>
        <p className="va-condition-tone" style={{ minHeight: item.tone ? '52px' : 'auto' }}>{item.tone || item.summary}</p>

        {item.engagement !== undefined && (
            <div className="mt-3">
                <Bar label={barLabels?.[0] || "참여 신호"} value={item.engagement} />
                <Bar label={barLabels?.[1] || "감정 표현"} value={item.affect} />
                <Bar label={barLabels?.[2] || "신뢰 인상"} value={item.trust} />
                <Bar label={barLabels?.[3] || "팀 시너지"} value={item.synergy} />
            </div>
        )}
    </div>
);

const ArticlePage = ({ post }) => {
    const { articleContent } = post;

    return (
        <div className="va-article">
            <section className="text-center pt-4 pb-5">
                <figure className="mb-2">
                    <div style={{ display: 'inline-block', maxWidth: '100%' }}>
                        <img src={post.image} alt={post.headline} className="img-fluid shadow-lg" style={{ maxHeight: '650px', width: 'auto', maxWidth: '100%', borderRadius: '30px' }} />
                        {post.caption && (
                            <figcaption className="text-end text-dark small mt-2 fst-italic">
                                {post.caption}
                            </figcaption>
                        )}
                    </div>
                </figure>

                {/* <div className="container">
            <h1 className="fw-bolder text-dark mb-3">{post.headline}</h1>
        </div> */}
            </section>

            {/* Research Question Section */}
            {articleContent.lead && (
                <section className="va-section">
                    <div className="va-section-heading">
                        <span>Research Question</span>
                        <h2>{post.headline}</h2>
                    </div>
          <div className="p-4 p-md-5 mx-auto" style={{ maxWidth: '100%' }}>
                        <p className="lead text-dark mb-0" style={{ textAlign: 'justify' }}>{articleContent.lead}</p>

            {/* Info Strip Section */}
            {articleContent.infoStrip && (
              <div className="va-question-strip mt-4" style={{ gridTemplateColumns: `repeat(${articleContent.infoStrip.length}, 1fr)` }}>
                {articleContent.infoStrip.map((item, index) => (
                  <div className="va-question-item" key={index}>
                    <FeatherIcon icon={item.icon} />
                    <span>{item.text}</span>
                  </div>
                ))}
              </div>
            )}
          </div>
          

                </section>
            )}



            {/* Content Sections */}
            {articleContent.sections?.map((section, index) => {
                switch (section.type) {
                    case 'story':
                        return (
                            <section className="va-section" key={index}>
                                <div className="va-section-heading">
                                    <span>{section.kicker}</span>
                                    <h2>{section.title}</h2>
                                </div>
                                <div className="va-story-list">
                                    {section.storySections.map((story, sIndex) => (
                                        <article className="va-story-card" key={sIndex}>
                                            <div className="va-story-index">{String(sIndex + 1).padStart(2, '0')}</div>
                                            <div>
                                                <span>{story.kicker}</span>
                                                <h3>{story.title}</h3>
                                                <p>{story.body}</p>
                                            </div>
                                        </article>
                                    ))}
                                </div>
                            </section>
                        );
                    case 'experiment':
                        return (
                            <section className="va-section" key={index}>
                                <div className="va-section-heading">
                                    <span>{section.kicker}</span>
                                    <h2>{section.title}</h2>
                                    <p>{section.body}</p>
                                </div>
                                <div className="va-condition-grid" style={{ gridTemplateColumns: section.layout === 'grid-3' ? 'repeat(3, 1fr)' : 'repeat(2, 1fr)' }}>
                                    {section.conditions.map(item => (
                                        <ConditionCard key={item.code} item={item} barLabels={section.barLabels} />
                                    ))}
                                </div>
                                {section.note && (
                                    <div className="va-note">
                                        <FeatherIcon icon="info" size={18} />
                                        <span>{section.note}</span>
                                    </div>
                                )}
                            </section>
                        );
                    case 'result':
                        return (
                            <section className="va-section va-result-panel" key={index}>
                                <div className="row g-4 align-items-stretch">
                                    <div className="col-lg-5">
                                        <div className="va-big-finding">
                                            <span>Key Finding</span>
                                            <h2>{section.keyFinding.title}</h2>
                                            <p>{section.keyFinding.body}</p>
                                        </div>
                                    </div>
                                    <div className="col-lg-7">
                                        {section.summaryTable && (
                                            <div className="va-table-card">
                                                <table>
                                                    <thead>
                                                        <tr>
                                                            {section.summaryTable.headers.map(h => <th key={h}>{h}</th>)}
                                                        </tr>
                                                    </thead>
                                                    <tbody>
                                                        {section.summaryTable.rows.map((row, rIndex) => (
                                                            <tr key={rIndex}>
                                                                {row.cells.map((cell, cIndex) => (
                                                                    <td key={cIndex} className={cell.className || ''}>
                                                                        {cell.text || cell}
                                                                    </td>
                                                                ))}
                                                            </tr>
                                                        ))}
                                                    </tbody>
                                                </table>
                                            </div>
                                        )}
                                        {section.barChart && (
                                            <div className="va-table-card">
                                                <div className="p-3">
                                                    {section.barChart.data.map(item => (
                                                        <div key={item.code} className="mb-3">
                                                            <strong className="d-block mb-2">{item.title}</strong>
                                                            <Bar label={section.barChart.labels[0]} value={item.sicknessTolerance} />
                                                            <Bar label={section.barChart.labels[1]} value={item.balanceImprovement} />
                                                            <Bar label={section.barChart.labels[2]} value={item.transferEffect} />
                                                        </div>
                                                    ))}
                                                </div>
                                            </div>
                                        )}
                                    </div>
                                </div>
                            </section>
                        );
                    
                    case 'takeaway':
                        return (
                            <section className="va-section va-takeaway" key={index}>
                                <div className="va-takeaway-card">
                                    <FeatherIcon icon={section.icon} />
                                    <div>
                                        <h2>{section.title}</h2>
                                        <p>{section.body}</p>
                                    </div>
                                </div>
                            </section>
                        );
                    default:
                        return null;
                }
            })}

            {/* Publication Info Card */}
            {post.paperUrl && (
                <section className="va-section va-publication-info">
                    <div className="va-publication-card d-flex justify-content-between align-items-center">
                        <div className="d-flex align-items-center">
                            <div>
                                <h4 className="fw-bolder mb-1">{post.paperTitle || post.headline}</h4>
                                {post.authors && <p className="text-muted small mb-1">{post.authors}</p>}
                                {post.journal && post.details && <p className="text-muted small mb-0">{post.journal}, {post.details}</p>}
                            </div>
                        </div>
                        <a href={post.paperUrl} target="_blank" rel="noopener noreferrer" className="va-primary-btn va-publication-btn flex-shrink-0 text-nowrap">
                            논문 바로가기
                        </a>
                    </div>
                </section>
            )}




        </div>
    );
};

const PostDetail = () => {
    const { id } = useParams();
    const post = postData.find(p => p.id === id);

    if (!post) {
        return <NotFound />;
    }

    return (
        <div className="container-xl px-4 mt-5 mb-5">
            <style>{`
        .va-article {
          color: #111827;
        }

        /* .va-eyebrow {
          // Removed as per user request to not have badge-like styling
        } */

        /* .va-lead {
          // Color changed to text-dark directly in JSX
        } */

        /* .va-hero-actions {
          // No changes requested for this block
        } */

        .va-primary-btn,
        .va-secondary-btn {
          display: inline-flex;
          align-items: center;
          justify-content: center;
          padding: 13px 20px;
          border-radius: 999px;
          text-decoration: none;
          font-weight: 800;
        }

        .va-primary-btn {
          background: #8b0029;
          color: #fff !important;
          box-shadow: 0 12px 24px rgba(139, 0, 41, 0.2);
        }

        .va-secondary-btn {
          background: #fff;
          color: #8b0029;
        }

        .va-question-strip {
          display: grid;
          grid-template-columns: repeat(4, 1fr);
          gap: 14px;
          /* margin: 32px 0; Removed as it's now nested and mt-4 handles top margin */
        }

        .va-question-item {
          display: flex;
          align-items: center;
          gap: 10px;
          padding: 18px;
          background: #ffffff;
          border: 1px solid #edf0f5;
          border-radius: 20px;
          box-shadow: 0 12px 30px rgba(15, 23, 42, 0.06);
          font-weight: 800;
          color: #263142;
        }

        .va-question-item svg {
          color: #8b0029;
          flex: 0 0 auto;
        }

        .va-section {
          margin-top: 38px;
          padding: 42px;
          background: #ffffff;
          border: 1px solid #edf0f5;
          border-radius: 30px;
          box-shadow: 0 18px 55px rgba(15, 23, 42, 0.07);
        }

        .va-section-heading {
          text-align: center;
          max-width: 100%;
          margin: 0 auto 32px;
        }

        .va-section-heading span {
          display: inline-block;
          color: #8b0029;
          font-weight: 900;
          letter-spacing: 0.08em;
          text-transform: uppercase;
          font-size: 0.78rem;
          margin-bottom: 10px;
        }

        .va-section-heading h2 {
          font-size: clamp(1.8rem, 3vw, 2.6rem);
          letter-spacing: -0.04em;
          font-weight: 900;
          margin-bottom: 12px;
        }

        .va-section-heading p {
          color: #5b6472;
          line-height: 1.75;
          margin-bottom: 0;
        }

        .va-condition-grid {
          display: grid;
          grid-template-columns: repeat(2, 1fr);
          gap: 18px;
        }

        .va-condition-card {
          position: relative;
          overflow: hidden;
          padding: 24px;
          border-radius: 24px;
          background: linear-gradient(180deg, #ffffff 0%, #fbfcff 100%);
          border: 1px solid #e7ebf2;
        }

        .va-condition-card.is-best {
          border: 2px solid rgba(139, 0, 41, 0.35);
          box-shadow: 0 18px 40px rgba(139, 0, 41, 0.12);
        }

        .va-code {
          display: inline-block;
          font-size: 0.78rem;
          font-weight: 900;
          color: #8b0029;
          background: rgba(139, 0, 41, 0.08);
          padding: 5px 9px;
          border-radius: 999px;
          margin-bottom: 9px;
        }

        .va-condition-card h4 {
          font-size: 1.35rem;
          font-weight: 900;
          margin: 0;
          letter-spacing: -0.03em;
        }

        .va-best-badge {
          padding: 6px 10px;
          border-radius: 999px;
          background: #8b0029;
          color: #fff;
          font-size: 0.75rem;
          font-weight: 900;
        }

        .va-condition-label {
          color: #111827;
          font-weight: 800;
          margin: 14px 0 6px;
        }

        .va-condition-tone {
          color: #687386;
          line-height: 1.65;
          font-size: 0.95rem;
          min-height: 52px;
        }

        .va-bar-row {
          display: grid;
          grid-template-columns: 76px 1fr 34px;
          gap: 10px;
          align-items: center;
          margin-top: 11px;
        }

        .va-bar-label {
          color: #4b5563;
          font-size: 0.82rem;
          font-weight: 800;
        }

        .va-bar-track {
          height: 10px;
          background: #edf0f5;
          border-radius: 999px;
          overflow: hidden;
        }

        .va-bar-fill {
          height: 100%;
          border-radius: 999px;
          background: linear-gradient(90deg, #8b0029, #e9789b);
        }

        .va-bar-value {
          color: #111827;
          font-size: 0.8rem;
          font-weight: 900;
          text-align: right;
        }

        .va-note {
          display: flex;
          gap: 10px;
          align-items: flex-start;
          margin-top: 20px;
          padding: 14px 16px;
          border-radius: 18px;
          background: #fff7ed;
          color: #7c4a03;
          font-size: 0.9rem;
          line-height: 1.6;
        }

        .va-result-panel {
          background:
            radial-gradient(circle at 5% 10%, rgba(139, 0, 41, 0.1), transparent 26%),
            linear-gradient(135deg, #111827, #253044);
          color: #fff;
          border: 0;
        }

        .va-big-finding {
          height: 100%;
          padding: 30px;
          border-radius: 26px;
          background: rgba(255,255,255,0.08);
          border: 1px solid rgba(255,255,255,0.16);
          backdrop-filter: blur(8px);
        }

        .va-big-finding span {
          color: #f5b4c7;
          font-weight: 900;
          text-transform: uppercase;
          letter-spacing: 0.08em;
          font-size: 0.78rem;
        }

        .va-big-finding h2 {
          margin-top: 14px;
          color: #ffffff;
          font-size: clamp(1.6rem, 3vw, 2.4rem);
          font-weight: 900;
          letter-spacing: -0.04em;
        }

        .va-big-finding p {
          color: rgba(255,255,255,0.78);
          line-height: 1.8;
          margin-top: 18px;
        }

        .va-table-card {
          height: 100%;
          overflow: hidden;
          border-radius: 26px;
          background: #fff;
          color: #111827;
        }

        .va-table-card table {
          width: 100%;
          border-collapse: collapse;
        }

        .va-table-card th {
          background: #f8fafc;
          color: #374151;
          font-size: 0.86rem;
          padding: 16px;
          border-bottom: 1px solid #e5e7eb;
        }

        .va-table-card td {
          padding: 16px;
          border-bottom: 1px solid #edf0f5;
          vertical-align: top;
          line-height: 1.55;
        }

        .va-table-card tr:last-child td {
          border-bottom: 0;
        }

        .positive {
          color: #047857;
          font-weight: 900;
        }

        .negative {
          color: #b91c1c;
          font-weight: 900;
        }

        .neutral {
          color: #6b7280;
          font-weight: 900;
        }

        .va-story-list {
          display: grid;
          gap: 18px;
        }

        .va-story-card {
          display: grid;
          grid-template-columns: 82px 1fr;
          gap: 20px;
          padding: 26px;
          border-radius: 24px;
          background: #fbfcff;
          border: 1px solid #e7ebf2;
        }

        .va-story-index {
          width: 58px;
          height: 58px;
          border-radius: 20px;
          display: flex;
          align-items: center;
          justify-content: center;
          background: #111827;
          color: #fff;
          font-weight: 900;
          font-size: 1.1rem;
        }

        .va-story-card span {
          color: #8b0029;
          font-weight: 900;
          font-size: 0.82rem;
          letter-spacing: 0.06em;
          text-transform: uppercase;
        }

        .va-story-card h3 {
          margin: 8px 0 10px;
          font-weight: 900;
          letter-spacing: -0.03em;
        }

        .va-story-card p {
          margin: 0;
          color: #4b5563;
          line-height: 1.85;
          font-size: 1.02rem;
          text-align: justify;
        }

        .va-takeaway {
          background: #fff7f7;
          border-color: rgba(139, 0, 41, 0.12);
        }

        .va-takeaway-card {
          display: flex;
          gap: 22px;
          align-items: flex-start;
        }

        .va-takeaway-card > svg {
          flex: 0 0 auto;
          width: 42px;
          height: 42px;
          color: #8b0029;
        }

        .va-takeaway-card h2 {
          font-weight: 900;
          letter-spacing: -0.04em;
          margin-bottom: 12px;
        }

        .va-takeaway-card p {
          color: #4b5563;
          line-height: 1.85;
          margin: 0;
          font-size: 1.05rem;
        }

        @media (max-width: 992px) {
          .va-hero {
            padding: 34px;
          }

          .va-question-strip,
          .va-condition-grid {
            grid-template-columns: 1fr 1fr;
          }
        }

        @media (max-width: 768px) {
          .va-hero {
            padding: 26px;
            border-radius: 24px;
          }

          .va-question-strip,
          .va-condition-grid {
            grid-template-columns: 1fr;
          }

          .va-section {
            padding: 26px;
            border-radius: 24px;
          }

          .va-story-card {
            grid-template-columns: 1fr;
          }

          .va-takeaway-card {
            flex-direction: column;
          }

          .va-condition-grid[style*="repeat(3"] {
            grid-template-columns: 1fr;
          }
        }
      `}</style>
            <style>{`
        .va-publication-info {
          margin-top: 38px;
          padding: 42px;
          background: #ffffff;
          border: 1px solid #edf0f5;
          border-radius: 30px;
          box-shadow: 0 18px 55px rgba(15, 23, 42, 0.07);
        }
        .va-publication-card {
          display: flex;
          flex-direction: row; /* Changed to row */
          align-items: center; /* Changed to center */
          text-align: left;
          padding: 24px;
          border-radius: 24px;
          background: linear-gradient(180deg, #fbfcff 0%, #ffffff 100%);
          border: 1px solid #e7ebf2;
        }
        .va-publication-card h4 {
          font-size: 1.5rem;
        .va-publication-btn {
          margin-top: 0; /* Removed margin-top */
        }
      `}</style>

            <div className="mb-4">
                <Link
                    to="/post"
                    className="text-decoration-none fw-bold d-inline-flex align-items-center"
                    style={{ color: '#8b0029' }}
                >
                    <FeatherIcon
                        icon="arrow-left"
                        className="me-1"
                        style={{
                            width: 16,
                            height: 16,
                            stroke: '#8b0029',
                            verticalAlign: 'middle',
                            position: 'relative',
                            top: '-1px'
                        }}
                    />
                    Back to Posts
                </Link>
            </div>

            {post.articleContent ? (
                <ArticlePage post={post} />
            ) : (
                <div className="card border-0 shadow-sm rounded-4 overflow-hidden p-4 p-md-5">
                    <figure className="mb-4">
                        <img
                            src={post.image}
                            alt={post.headline}
                            className="img-fluid rounded-3 shadow-sm mx-auto d-block"
                            style={{ objectFit: 'contain' }}
                        />
                        {post.caption && (
                            <figcaption className="text-end text-muted small mt-2 fst-italic">
                                {post.caption}
                            </figcaption>
                        )}
                    </figure>

                    <div className="row justify-content-center">
                        <div className="col-lg-8">
                            <article>
                                <header className="mb-4">
                                    <div className="d-flex justify-content-between align-items-baseline">
                                        <h1 className="fw-bolder mb-1">{post.headline}</h1>
                                        <div className="text-muted small ms-3 text-nowrap">
                                            Posted on {post.date}
                                        </div>
                                    </div>
                                </header>
                                <section className="mb-5">
                                    <p
                                        className="fs-5 mb-4"
                                        style={{ lineHeight: '1.8', textAlign: 'justify', whiteSpace: 'pre-line' }}
                                    >
                                        {post.description}
                                    </p>
                                </section>
                            </article>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default PostDetail;