import React from 'react';
import { Link } from 'react-router-dom';
import FeatherIcon from 'feather-icons-react';

const NotFound = () => {
  const tigerImage = process.env.PUBLIC_URL + '/assets/img/profile/students.jpg';

  return (
    <div className="container-xl px-4 mt-5 mb-5 text-center">
      <style>
        {`
          .error-code {
            font-size: 10rem;
            font-weight: 900;
            color: #8b0029;
            line-height: 1;
            text-shadow: 4px 4px 0 rgba(0,0,0,0.1);
          }
          .error-message {
            font-size: 2.5rem;
            font-weight: 700;
            color: #212529;
            margin-bottom: 1.5rem;
          }
          .error-subtext {
            font-size: 1.2rem;
            color: #6c757d;
            margin-bottom: 2.5rem;
          }
          .tiger-image {
            width: 300px; /* Fixed width for circular shape */
            height: 300px; /* Fixed height for circular shape */
            object-fit: cover; /* Ensures the image covers the area without distortion */
            border-radius: 50%; /* Makes the image perfectly circular */
            box-shadow: 0 10px 30px rgba(0,0,0,0.1);
            margin-bottom: 3rem;
          }
          .btn-go-home {
            background-color: #8b0029;
            color: white;
            border: none;
            padding: 1rem 2rem;
            font-size: 1.1rem;
            font-weight: bold;
            border-radius: 8px;
            transition: all 0.3s ease;
          }
          .btn-go-home:hover {
            background-color: #6d001a;
            transform: translateY(-2px);
            box-shadow: 0 5px 15px rgba(0,0,0,0.2);
             color: #ffffff; 
          }
          .btn-go-home svg {
            stroke: white;
          }
        `}
      </style>
      <div className="py-5">
        <h1 className="error-code">404</h1>
        <p className="error-message">Out of Field-Of-View</p>
        <p className="error-subtext">
          시야 범위를 벗어난 페이지입니다. 요청하신 페이지를 찾을 수 없습니다.
        </p>
        <img src={tigerImage} alt="Out of FOV Tiger" className="tiger-image" />
        <div>
          <Link to="/" className="btn btn-go-home d-inline-flex align-items-center">
            <FeatherIcon icon="home" className="me-2" style={{ width: 20, height: 20 }} />
            홈으로 돌아가기
            
          </Link>
        </div>
      </div>
    </div>
  );
};

export default NotFound;