import React, { useEffect, useState, useRef } from 'react';
import { Modal } from 'react-bootstrap';
import FeatherIcon from 'feather-icons-react';
import { ComposableMap, Geographies, Geography, Marker, ZoomableGroup } from 'react-simple-maps';

// Sample travel data (latitude, longitude)
// Note: These are simplified coordinates for illustrative purposes on a flat SVG map.
// For accurate geographical plotting, a proper map library with projection is needed.
const travelData = [
  { city: 'Seoul', coords: [126.9780, 37.5665], conference: 'IMX Lab (Home)' },
  { city: 'NARA', coords: [135.5023, 34.6937], conference: 'NAIST' },
  { city: 'Taipei', coords: [121.5654, 25.0330], conference: 'APMAR 2023' },
  { city: 'Shanghai', coords: [121.4737, 31.2304], conference: 'IEEE VR 2023' },
  { city: 'San Diego', coords: [-117.1611, 32.7157], conference: 'Qualcomm Institute' },
  { city: 'Hawaii', coords: [-157.8581, 21.3069], conference: 'ACM CHI 2024' },
  { city: 'Christchurch', coords: [172.6362, -43.5320], conference: 'ACM VRST 2023' },
  { city: 'Trier', coords: [6.6371, 49.7499], conference: 'ACM VRST 2024' },
  { city: 'Tokyo', coords: [139.6503, 35.6762], conference: 'SIGGRAPH Asia 2024' },
  { city: 'Yokohama', coords: [139.6380, 35.4437], conference: 'ACM CHI 2025' },
];

// Define routes between cities (using city names for easier lookup)
const travelRoutes = [
  { from: 'Seoul', to: 'NARA' },
  { from: 'Seoul', to: 'Taipei' },
  { from: 'Seoul', to: 'Shanghai' },
  { from: 'Seoul', to: 'San Diego' },
  { from: 'Seoul', to: 'Hawaii' },
  { from: 'Seoul', to: 'Christchurch' },
  { from: 'Seoul', to: 'Trier' },
  { from: 'Seoul', to: 'Tokyo' },
  { from: 'Seoul', to: 'Yokohama' },
];

// 지도 지형을 그리기 위한 무료 TopoJSON 데이터 URL
const geoUrl = "https://cdn.jsdelivr.net/npm/world-atlas@2/countries-110m.json";

const ResearchTravelMap = () => {
  const [showModal, setShowModal] = useState(false);
  
  // 지도의 줌 배율을 높여 불필요한 바다 영역 제거 (1.05 -> 1.4)
  const [position, setPosition] = useState({ coordinates: [130, 15], zoom: 1.4 });
  const [selectedCity, setSelectedCity] = useState(null); // 선택된 도시(마커) 상태 추적
  const animationTimeouts = useRef([]); // 애니메이션 타이머 추적
  const isAnimating = useRef(false); // 애니메이션 실행 중 상태 추적

  const animationFrame = useRef(null);
  const positionRef = useRef(position);

  useEffect(() => {
    positionRef.current = position;
  }, [position]);

  useEffect(() => {
    return () => {
      if (animationFrame.current) {
        cancelAnimationFrame(animationFrame.current);
      }
    };
  }, []);

  const cancelMapAnimation = () => {
    if (animationFrame.current) {
      cancelAnimationFrame(animationFrame.current);
      animationFrame.current = null;
    }
    isAnimating.current = false;
  };

  const easeInOutCubic = (t) => (
    t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2
  );

  const interpolateLongitude = (from, to, t) => {
    let delta = to - from;
    if (delta > 180) delta -= 360;
    if (delta < -180) delta += 360;

    let next = from + delta * t;
    if (next > 180) next -= 360;
    if (next < -180) next += 360;
    return next;
  };

  const animateMapTo = (targetPosition, duration = 950) => {
    cancelMapAnimation();

    const startPosition = positionRef.current;
    const startCoords = startPosition.coordinates;
    const targetCoords = targetPosition.coordinates;
    let startTime = null;

    isAnimating.current = true;

    const step = (timestamp) => {
      if (!startTime) startTime = timestamp;

      const progress = Math.min((timestamp - startTime) / duration, 1);
      const eased = easeInOutCubic(progress);
      const nextPosition = {
        coordinates: [
          interpolateLongitude(startCoords[0], targetCoords[0], eased),
          startCoords[1] + (targetCoords[1] - startCoords[1]) * eased,
        ],
        zoom: startPosition.zoom + (targetPosition.zoom - startPosition.zoom) * eased,
      };

      positionRef.current = nextPosition;
      setPosition(nextPosition);

      if (progress < 1) {
        animationFrame.current = requestAnimationFrame(step);
        return;
      }

      animationFrame.current = null;
      isAnimating.current = false;
    };

    animationFrame.current = requestAnimationFrame(step);
  };

  const handleShowModal = () => {
    setShowModal(true);
    cancelMapAnimation();
    positionRef.current = { coordinates: [130, 15], zoom: 1.4 };
    setSelectedCity(null); // 모달을 열 때 선택 상태 초기화
    setPosition({ coordinates: [130, 15], zoom: 1.4 }); // 지도를 초기 시점으로 리셋
    animationTimeouts.current.forEach(t => clearTimeout(t)); // 진행 중인 애니메이션 초기화
    isAnimating.current = false;
  };
  const handleCloseModal = () => {
    setShowModal(false);
    cancelMapAnimation();
    positionRef.current = { coordinates: [130, 15], zoom: 1.4 };
    setSelectedCity(null); // 모달을 닫을 때 선택 상태 초기화
    setPosition({ coordinates: [130, 15], zoom: 1.4 });
    animationTimeouts.current.forEach(t => clearTimeout(t));
    isAnimating.current = false;
  };

  // 도시 선택 시 줌인 애니메이션을 위한 핸들러
  const handleCitySelect = (cityName) => {
    setSelectedCity(cityName);
    const cityInfo = travelData.find(c => c.city === cityName);
    
    if (cityInfo) {
      // 기존 진행 중인 애니메이션 타이머 취소 (빠른 연속 클릭 시 꼬임 방지)
      animationTimeouts.current.forEach(t => clearTimeout(t));
      animationTimeouts.current = [];
      isAnimating.current = true; // 애니메이션 진행 중으로 플래그 설정

      const seoulCoords = [126.9780, 37.5665];
      const targetCoords = cityInfo.coords;
      
      // 1. 태평양 횡단 등을 고려하여 경도의 연속성 보정 (예: 미국, 하와이)
      let lon1 = seoulCoords[0];
      let lon2 = targetCoords[0];
      if (lon2 < 0) lon2 += 360; 
      
      // 2. 한국(서울)과 목적지의 정중앙 좌표 계산
      const midLon = (lon1 + lon2) / 2;
      const finalMidLon = midLon > 180 ? midLon - 360 : midLon;
      const midLat = (seoulCoords[1] + targetCoords[1]) / 2;
      
      // 3. 두 지점 간의 거리에 따른 동적 줌 배율 계산 (양쪽 여백을 위해 +60도 패딩 적용)
      const lonDiff = Math.abs(lon1 - lon2);
      const latDiff = Math.abs(seoulCoords[1] - targetCoords[1]);
      
      const zoomLon = 360 / (lonDiff + 60);
      const zoomLat = 180 / (latDiff + 60);
      
      // 화면 밖으로 잘리지 않게 가로/세로 중 더 많이 축소해야 하는 줌 배율 선택
      let targetZoom = Math.min(zoomLon, zoomLat);
      
      // 줌이 너무 심하게 되거나 너무 작아지지 않도록 최소/최대값 제한
      targetZoom = Math.max(1.4, Math.min(targetZoom, 4.0));

      // [버그 수정] D3.js 애니메이션 엔진의 내부 트랜지션과 React 상태가 충돌하지 않도록 
      // 인위적인 단계별 setTimeout 딜레이를 제거하고, 목표 지점과 줌 배율을 한 번에 세팅합니다.
      // D3의 기본 보간법(d3.interpolateZoom)이 작동하여 가장 매끄럽게(버벅임 없이) 이동합니다.
      animateMapTo({ coordinates: [finalMidLon, midLat], zoom: targetZoom });

      // 카메라 이동 완료(약 400ms) 후 플래그 해제
    }
  };

  return (
    <>
      <style>
        {`
          .research-travel-card {
            cursor: pointer;
            transition: all 0.2s ease;
            border-radius: 12px;
            background-color: rgba(40, 167, 69, 0.05);
            border: 1px solid rgba(40, 167, 69, 0.2);
            position: relative;
            overflow: hidden;
          }
          .research-travel-card:hover {
            background-color: rgba(40, 167, 69, 0.1) !important;
            transform: translateY(-2px);
          }
          @keyframes pulse-green {
            0% { transform: scale(0.95); box-shadow: 0 0 0 0 rgba(40, 167, 69, 0.7); }
            70% { transform: scale(1); box-shadow: 0 0 0 6px rgba(40, 167, 69, 0); }
            100% { transform: scale(0.95); box-shadow: 0 0 0 0 rgba(40, 167, 69, 0); }
          }
          .blob-green {
            background: #28a745;
            border-radius: 50%;
            height: 12px;
            width: 12px;
            animation: pulse-green 2s infinite;
          }
          .research-travel-bg {
            position: absolute;
            right: 10px; /* 카드 안쪽으로 조금 더 들어오도록 위치 조정 */
            top: 50%;
            transform: translateY(-50%);
            height: 85%; /* 이미지 크기를 조금 더 작게 축소 */
            object-fit: contain;
            opacity: 0.15; /* 은은한 느낌을 주는 투명도 */
            pointer-events: none; /* 클릭을 방해하지 않음 */
            transition: all 0.3s ease;
          }
          .research-travel-card:hover .research-travel-bg {
            opacity: 0.3; /* 마우스를 올렸을 때 살짝 더 선명해짐 */
            transform: translateY(-50%) scale(1.05);
          }
          .modal-map-svg {
            width: 100%;
            height: auto;
            /* background-image 속성 제거 */
            border-radius: 8px;
          }
          .travel-line {
            stroke: #ff5177; /* Red fluorescent color */
            filter: drop-shadow(0 0 5px #ff5177) drop-shadow(0 0 10px #ff5177); /* Fluorescent effect */
            animation: drawLine 2s ease-out forwards;
          }
          .travel-point {
            fill: #8b0029; /* Darker red for points */
            stroke: white;
            stroke-width: 1;
            filter: drop-shadow(0 0 3px rgba(255,81,119,0.8));
            transition: fill 0.3s ease;
          }
          .travel-point:hover {
            fill: #ff5177; /* 마우스 호버 시 핀 색상 밝게 */
          }
          @keyframes drawLine {
            from {
              stroke-dashoffset: 1500; /* 곡선으로 인해 늘어난 길이를 반영하여 수정 */
            }
            to {
              stroke-dashoffset: 0;
            }
          }
          .modal-custom-close-btn {
            background: transparent;
            border: none;
            color: #adb5bd;
            width: 48px;
            height: 48px;
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            transition: all 0.3s ease-in-out;
            cursor: pointer;
            margin-left: auto;
          }
          .modal-custom-close-btn:hover,
          .modal-custom-close-btn:focus {
            color: #212529;
            background-color: rgba(0, 0, 0, 0.05);
            transform: rotate(90deg);
            outline: none;
          }
          .modal-custom-close-btn svg {
            width: 32px !important;
            height: 32px !important;
            stroke-width: 2.5px;
            stroke: currentColor;
          }
          .conference-item {
            transition: all 0.2s ease;
            border-left: 4px solid transparent !important;
            background-color: transparent;
          }
          .conference-item:hover {
            background-color: rgba(0, 0, 0, 0.03);
          }
          .active-conference {
            background-color: rgba(255, 81, 119, 0.08) !important;
            border-left: 4px solid #ff5177 !important;
          }
          .conference-list-scroll::-webkit-scrollbar {
            width: 6px;
          }
          .conference-list-scroll::-webkit-scrollbar-track {
            background: #ffffff;
            border-radius: 4px;
          }
          .conference-list-scroll::-webkit-scrollbar-thumb {
            background: #dee2e6;
            border-radius: 4px;
          }
          .conference-list-scroll::-webkit-scrollbar-thumb:hover {
            background: #adb5bd;
          }
        `}
      </style>

      {/* Research Travel Card */}
      <div className="card shadow-sm mb-3 research-travel-card" onClick={handleShowModal} title="해외 학회 참여 기록 보기">
        {/* 배경으로 쓰일 은은한 세계 지도 이미지 */}
        <img 
          src={process.env.PUBLIC_URL + '/assets/img/world-map.png'} 
          alt="World Map Background" 
          className="research-travel-bg" 
        />
        <div className="card-body p-3 d-flex align-items-center position-relative" style={{ zIndex: 1 }}>
          <div className="blob-green flex-shrink-0 m-0 me-3"></div>
          <div>
            <div className="fw-bolder" style={{ color: '#28a745', fontSize: '1.1rem', letterSpacing: '-0.2px' }}>Research Travel</div>
            <div className="text-dark fw-bold mt-1" style={{ fontSize: '0.9rem', letterSpacing: '-0.3px', wordBreak: 'keep-all' }}>국내외 학회 참여 기록</div>
            <div className="text-dark mt-2 fw-bold d-flex align-items-center" style={{ fontSize: '0.8rem' }}>
               자세히 보기 <FeatherIcon icon="map" style={{ width: 16, height: 16, marginLeft: '8px', stroke: '#28a745' }} />
            </div>
          </div>
        </div>
      </div>

      {/* Research Travel Modal */}
      <Modal show={showModal} onHide={handleCloseModal} centered size="xl">
        <Modal.Header style={{ backgroundColor: '#ffffff', borderBottom: '1px solid #dee2e6' }}>
          <Modal.Title className="text-dark fw-bolder">
            {/* <FeatherIcon icon="map" className="me-2" style={{ width: 24, height: 24, stroke: 'white' }} />  */}
            Our Research Journey
          </Modal.Title>
          <button type="button" className="modal-custom-close-btn" onClick={handleCloseModal} aria-label="Close">
            <FeatherIcon icon="x" size="28" />
          </button>
        </Modal.Header>
        <Modal.Body className="p-0" style={{ backgroundColor: '#f8f9fa' }}> {/* 모달 배경색을 밝게 변경 */}
          <div className="d-flex flex-column flex-lg-row h-100">
            {/* 70% 비율: 지도 영역 */}
            <div style={{ flex: '7' }} className="position-relative p-2 p-md-3 d-flex flex-column justify-content-center">
              <ComposableMap 
                projection="geoMercator" 
                width={800}
                height={450}
                projectionConfig={{ rotate: [-127, 0, 0] }} /* 한국(경도 127)을 중앙으로 오게 지구본을 회전 */
                className="modal-map-svg" 
                style={{ width: '100%', height: 'auto' }}
              >
                {/* ZoomableGroup을 추가하여 드래그와 확대/축소 활성화 */}
                <ZoomableGroup 
                  center={position.coordinates} 
                  zoom={position.zoom} 
                  onMoveEnd={pos => {
                    // 시네마틱 카메라 비행 중에는 상태 업데이트를 무시하여 지도가 튀는 버그 완벽 차단
                    if (!isAnimating.current) setPosition(pos);
                  }}
                  minZoom={0.5} 
                  maxZoom={5}
                >
                  <Geographies geography={geoUrl}>
                    {({ geographies, projection }) => (
                      <>
                        {geographies.map((geo) => (
                          <Geography
                            key={geo.rsmKey}
                            geography={geo}
                            fill="#EAEAEC"
                            stroke="#D6D6DA"
                            strokeWidth={0.5}
                            style={{
                              default: { outline: "none" },
                              hover: { fill: "#D6D6DA", outline: "none" },
                              pressed: { outline: "none" },
                            }}
                          />
                        ))}
            
                        {/* Draw travel routes (Curved) */}
                        {travelRoutes.map((route, index) => {
                          const fromCity = travelData.find(c => c.city === route.from);
                          const toCity = travelData.find(c => c.city === route.to);
                          
                          if (fromCity && toCity && selectedCity === route.to) { // 클릭한 지역의 경로만 그림
                            const [startX, startY] = projection(fromCity.coords);
                            const [endX, endY] = projection(toCity.coords);
                            
                            const dx = endX - startX;
                            const dy = endY - startY;
                            
                            // 법선 벡터(Normal Vector)를 구하여 곡선의 휨 방향을 항상 위쪽(북쪽)으로 고정
                            let nx = dy;
                            let ny = -dx;
                            if (ny > 0) {
                              nx = -nx;
                              ny = -ny;
                            }
                            
                            // 곡선의 휘어짐 정도 (0에 가까울수록 직선, 숫자가 커질수록 많이 휨)
                            const curveIntensity = 0.25; 
                            const cx = (startX + endX) / 2 + nx * curveIntensity;
                            const cy = (startY + endY) / 2 + ny * curveIntensity;
      
                            return (
                              <path
                                key={`${index}-${selectedCity}`}
                                d={`M ${startX},${startY} Q ${cx},${cy} ${endX},${endY}`}
                                className="travel-line"
                                fill="transparent"
                                style={{ 
                                  strokeDasharray: 1500, 
                                  strokeDashoffset: 1500, 
                                  animationDelay: `0.4s`, /* 카메라 이동(약 0.4초)이 끝난 후 선이 뻗어나가도록 지연 맞춤 */
                                  /* 줌 배율에 반비례하게 선 굵기 조절하여 일정한 굵기 유지 */
                                  strokeWidth: 3 / position.zoom 
                                }}
                              />
                            );
                          }
                          return null;
                        })}
                      </>
                    )}
                  </Geographies>
      
                  {/* Draw visited locations */}
                  {travelData.map((location, index) => (
                    <Marker 
                      key={index} 
                      coordinates={location.coords}
                      onClick={() => handleCitySelect(location.city)} // 마커 클릭 시 해당 도시를 선택 및 줌인
                      style={{ cursor: 'pointer' }}
                    >
                      {/* 줌 배율(position.zoom)의 역수로 스케일을 조정해 마커/텍스트가 일정한 크기를 유지하도록 함 */}
                      <g transform={`scale(${1 / position.zoom})`}>
                        <g>
                          {/* 선택 시 파동(Pulse) 애니메이션 효과 */}
                          {selectedCity === location.city && (
                            <circle cx="0" cy="0" r="12" fill="none" stroke="#ff5177" strokeWidth="2">
                              <animate attributeName="r" from="5" to="20" dur="1.5s" repeatCount="indefinite" />
                              <animate attributeName="opacity" from="0.8" to="0" dur="1.5s" repeatCount="indefinite" />
                            </circle>
                          )}
                          {/* 모던 심플 원형 마커 */}
                          <circle
                            cx="0"
                            cy="0"
                            r={selectedCity === location.city ? 7 : 5}
                            className="travel-point"
                            style={{ 
                              fill: selectedCity === location.city ? '#ff5177' : '', 
                              stroke: '#ffffff', 
                              strokeWidth: 1.5,
                              transition: 'all 0.3s ease'
                            }}
                          />
                        </g>
                        {/* Conference Label (해당 마커를 선택했을 때만 마커 위쪽에 표시) */}
                        {selectedCity === location.city && location.conference && (
                          <text
                            textAnchor="middle"
                            y={-30}
                            style={{ fontFamily: "system-ui", fill: "#ff5177", fontSize: "13px", fontWeight: "900", pointerEvents: "none", textShadow: "1px 1px 2px white, -1px -1px 2px white, 1px -1px 2px white, -1px 1px 2px white" }}
                          >
                            {location.conference}
                          </text>
                        )}
                        {/* City Label */}
                        <text
                          textAnchor="middle"
                          y={-14}
                          style={{ fontFamily: "system-ui", fill: "#212529", fontSize: "11px", fontWeight: "800", pointerEvents: "none", textShadow: "1px 1px 2px white, -1px -1px 2px white, 1px -1px 2px white, -1px 1px 2px white" }}
                        >
                          {location.city}
                        </text>
                      </g>
                    </Marker>
                  ))}
                </ZoomableGroup>
              </ComposableMap>
            </div>
            
            {/* 30% 비율: 우측 리스트 영역 */}
            <div style={{ flex: '3' }} className="bg-white border-start p-4 d-flex flex-column">
              <h5 className="fw-bolder mb-4" style={{ color: '#8b0029' }}>
                <FeatherIcon icon="list" className="me-2" style={{ stroke: '#8b0029', width: 18, height: 18, verticalAlign: 'middle' }} />
                Visited countries
              </h5>
              {/* 지도 높이와 딱 맞도록 리스트의 최대 높이를 340px로 축소하여 모달 위아래 공백 제거 */}
              <div className="list-group list-group-flush conference-list-scroll" style={{ overflowY: 'auto', maxHeight: '340px', paddingRight: '4px' }}>
                {/* 서울(Home)을 제외한 다녀온 학회 리스트 렌더링 */}
                {travelData.filter(loc => loc.city !== 'Seoul').map((location, index) => (
                  <div 
                    key={index}
                    className={`list-group-item list-group-item-action border-0 mb-2 rounded conference-item ${selectedCity === location.city ? 'active-conference' : ''}`}
                    onClick={() => handleCitySelect(location.city)} // 리스트 클릭 시 지도 마커와 동일한 액션 트리거 및 줌인
                    style={{ cursor: 'pointer' }}
                  >
                    <div className="fw-bold" style={{ fontSize: '1rem', color: selectedCity === location.city ? '#8b0029' : '#212529' }}>
                      {location.conference}
                    </div>
                    <div className="text-muted small mt-1 d-flex align-items-center">
                      <FeatherIcon icon="map-pin" style={{ width: 12, height: 12, marginRight: '4px' }} />
                      {location.city}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </Modal.Body>
        <Modal.Footer style={{ backgroundColor: '#ffffff', borderTop: '1px solid #dee2e6' }}>
          <p className="text-muted small mb-0">
            지도 마커나 우측 리스트를 클릭하여 해당 지역에서 참여한 학회를 확인해 보세요.
          </p>
        </Modal.Footer>
      </Modal>
    </>
  );
};

export default ResearchTravelMap;
